// Flatten with platform/city/country metadata
const events = [];
for (const [platform, cities] of Object.entries(RAW)) {
  for (const [city, evs] of Object.entries(cities)) {
    for (const e of evs) {
      events.push({ platform, city, country: COUNTRIES[city], ...e });
    }
  }
}

// Inject into HTML
const htmlPath = join(root, 'aggregation.html');
const html = readFileSync(htmlPath, 'utf8');
const json = JSON.stringify(events);
const out = html.replace('"events": EVENTS_PLACEHOLDER', '"events": ' + json);
writeFileSync(htmlPath, out);

const byPlatform = events.reduce((a, e) => (a[e.platform] = (a[e.platform] || 0) + 1, a), {});
const byCountry = events.reduce((a, e) => (a[e.country] = (a[e.country] || 0) + 1, a), {});
console.log(`✓ Wrote ${events.length} events to aggregation.html`);
console.log(`  By platform:`, byPlatform);
console.log(`  By country:`, byCountry);
